         for ( int j=0; j< mult; j++ )
             my->knots.push_unsorted( *itr );

     for ( int j=0; j<degree+1-mult; j++ ) // adjust multiplicity last knot
         my->knots.push_unsorted( knots.back() );

     my->p=degree;
     my->knots.SetSorted();

