            M.row(i).swap(M.row(r));
            if ( 0 != M(r, piv) ) //~
                M.row(r).array() /= M(r, piv);
            for (i=0; i !=r; ++i)
                M.row(i).array() -= M(i, piv) * M.row(r).array();
            for (++i; i !=nr; ++i)
                M.row(i).array() -= M(i, piv) * M.row(r).array();
            ++piv;
