template<class T>
T gsBasis<T>::getMinCellLength() const
{
    const domainIter it = this->makeDomainIterator();
    T h = 0;
    for (; it->good(); it->next() )
    {
        const T sz = it->getMinCellLength();
        if ( sz < h || h == 0 ) h = sz;
    }
    return h;
}

template<class T>
T gsBasis<T>::getMaxCellLength() const
{
    const domainIter it = this->makeDomainIterator();
    T h = 0;
    for (; it->good(); it->next() )
    {
        const T sz = it->getMaxCellLength();
        if ( sz > h ) h = sz;
    }
    return h;
}

