      int count=1;
      T x1=0,x2=0,y1=0,y2=0,z1=0,z2=0;
      while(myfile >> line)
      {

          if(count==1)
              x1 = atof(line.c_str());
          else if(count==2)
              y1 = atof(line.c_str());
          else if(count==3)
              z1 = atof(line.c_str());
          else if(count==4)
              x2 = atof(line.c_str());
          else if(count==5)
              y2 = atof(line.c_str());
          else if(count==6)
          {
              z2 = atof(line.c_str());
              gsVertex<T> * v1 = new gsVertex<T>(x1,y1,z1);
              gsVertex<T> * v2 = new gsVertex<T>(x2,y2,z2);

              if(Xless<T>(v1,v2))std::swap(v1,v2);
              gsEdge<T> featureEdge(v1,v2);
              edges.push_back(featureEdge);

              count-=6;
          }
          count++;
      }

      myfile.close();
    }

