                ss <<" "<< t;
                m= 0;
                c++;
            }
            else {                                  /* digit + - E e D d */
                t[m]= s[i];
                m++;
                break;
            }

            if (c == (b[0]+1)*(b[1]+1))
            {
                ss<<",";
                c=0;
                phase=3; //control points start
            }
            break;
        }
    }
