 #       ifdef GISMO_WITH_PARDISO
         if (slv=="PardisoLU")        return uPtr(new PardisoLU());
         if (slv=="PardisoLDLT")      return uPtr(new PardisoLDLT());
         if (slv=="PardisoLLT")       return uPtr(new PardisoLLT());
 #       endif
