        _G.data().flags |= NEED_GRAD | NEED_DERIV2;
    }

    index_t cols() const { return 1; }

    void parse(gsExprHelper<Scalar> & evList) const
    {
        evList.add(_G);
        _G.data().flags |= NEED_GRAD | NEED_DERIV2;
    }

    void print(std::ostream &os) const { os << "dEdσ("; _G.print(os); os <<")"; }
};

